'use strict';
/* Component lab for the UI components page (#ux).
   40 native HTML/CSS components replace the raster previews. Each one is drawn in every
   state it supports, in any of the 20 Atlas themes, light or dark, comfortable or compact.
   The code tab exports exactly the HTML and CSS the stage renders. */
(()=>{
 const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const I={
  heart:'<path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10Z"/>',
  bookmark:'<path d="M7 4h10v16l-5-4-5 4Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>',
  chevron:'<path d="m7 10 5 5 5-5"/>',right:'<path d="m10 7 5 5-5 5"/>',left:'<path d="m14 7-5 5 5 5"/>',check:'<path d="m5 12 4.5 4.5L19 7"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>',
  home:'<path d="M4 11 12 4l8 7v9h-5v-6H9v6H4Z"/>',grid:'<path d="M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 20c1.5-4 4.5-6 8-6s6.5 2 8 6"/>',bell:'<path d="M6 16V11a6 6 0 0 1 12 0v5l2 2H4Z"/><path d="M10 20a2 2 0 0 0 4 0"/>',
  file:'<path d="M7 3h7l5 5v13H7Z"/><path d="M14 3v5h5"/>',upload:'<path d="M12 16V5M7 10l5-5 5 5M5 19h14"/>',cal:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M9 3v4M15 3v4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.5"/>',warn:'<path d="M12 4 2.5 20h19Z"/><path d="M12 10v5M12 17.5v.5"/>',folder:'<path d="M3 6h7l2 2h9v11H3Z"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',more:'<circle cx="6" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="18" cy="12" r="1.3"/>'
 };
 const ic=(n,l='')=>`<svg class="cl-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[n]}</svg>${l}`;
 const spin='<span class="cl-spin" aria-hidden="true"></span>';
 const btn=(t,cls='',attr='')=>`<button type="button" class="cl-btn ${cls}" ${attr}>${t}</button>`;
 const field=(label,inner,hint='',err='')=>`<div class="cl-field${err?' is-error':''}"><label class="cl-label">${label}</label>${inner}${err?`<p class="cl-msg cl-err">${ic('warn')}${err}</p>`:hint?`<p class="cl-msg">${hint}</p>`:''}</div>`;
 const V=(...a)=>a.map(x=>x.split(':'));
 const has=(v,...k)=>k.includes(v);

 const BASE=`.cl-root{font-family:var(--cl-font);color:var(--cl-text);font-size:15px;line-height:1.45}
.cl-root *,.cl-root *::before,.cl-root *::after{box-sizing:border-box}
.cl-ic{width:18px;height:18px;flex:none}
.cl-surface{background:var(--cl-surface);border:var(--cl-bw) solid var(--cl-line);border-radius:var(--cl-radius);box-shadow:var(--cl-shadow);-webkit-backdrop-filter:var(--cl-glass);backdrop-filter:var(--cl-glass)}
.cl-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:var(--cl-h);padding:var(--cl-pad);font:var(--cl-weight) 14px/1 var(--cl-font);border-radius:var(--cl-radius);border:var(--cl-bw) solid var(--cl-line);background:var(--cl-surface);color:var(--cl-text);box-shadow:var(--cl-shadow);cursor:pointer;transition:transform .15s,filter .15s,background .15s,box-shadow .15s}
.cl-btn.primary{background:var(--cl-accent-grad);border-color:var(--cl-accent);color:var(--cl-on-accent)}
.cl-btn.danger{color:var(--cl-danger);border-color:var(--cl-danger)}
.cl-btn:hover,.cl-btn.is-hover{filter:brightness(1.06);transform:translateY(-1px)}
.cl-btn:active,.cl-btn.is-active{transform:translateY(1px) scale(.98);filter:brightness(.95)}
.cl-btn:focus-visible,.cl-btn.is-focus,.cl-focusable:focus-visible,.is-focus>.cl-focusable{outline:2px solid var(--cl-accent);outline-offset:3px}
.cl-btn[disabled],.is-disabled{opacity:.45;cursor:not-allowed;transform:none;filter:none}
.cl-btn.icon{width:var(--cl-h);padding:0}
.cl-spin{width:14px;height:14px;border-radius:50%;border:2px solid currentColor;border-right-color:transparent;animation:cl-spin .8s linear infinite}
@keyframes cl-spin{to{transform:rotate(1turn)}}
.cl-field{display:grid;gap:6px;min-width:0}
.cl-label{font-size:13px;font-weight:600;color:var(--cl-text)}
.cl-input{width:100%;min-height:var(--cl-h);padding:var(--cl-pad);font:400 15px/1.3 var(--cl-font);color:var(--cl-text);background:var(--cl-surface);border:max(1px,var(--cl-bw)) solid var(--cl-line);border-radius:var(--cl-radius-sm);box-shadow:var(--cl-shadow);-webkit-backdrop-filter:var(--cl-glass);backdrop-filter:var(--cl-glass);outline:0;display:flex;align-items:center;gap:8px}
.cl-input:hover,.is-hover .cl-input{border-color:var(--cl-muted)}
.cl-input:focus,.cl-input:focus-within,.is-focus .cl-input{border-color:var(--cl-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--cl-accent) 25%,transparent)}
.is-error .cl-input{border-color:var(--cl-danger)}
.cl-msg{margin:0;font-size:12.5px;color:var(--cl-muted);display:flex;gap:6px;align-items:center}
.cl-err{color:var(--cl-danger)}.cl-err .cl-ic{width:14px;height:14px}
.cl-muted{color:var(--cl-muted)}
.cl-row{display:flex;flex-wrap:wrap;gap:var(--cl-gap);align-items:center}
.cl-stack{display:grid;gap:var(--cl-gap)}
.cl-h{font:var(--cl-weight) 18px/1.2 var(--cl-display);margin:0}
.cl-chip{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;font-size:12.5px;font-weight:600;border:1px solid var(--cl-line);background:var(--cl-surface)}`;

 const C=[
 {id:'C01',name:'Buttons',v:V('default:Default','hover:Hover','focus:Focus','active:Pressed','disabled:Disabled','loading:Loading'),
  html:(v,p)=>{const st=has(v,'hover','focus','active')?'is-'+v:'';const d=v==='disabled'?'disabled':'';const ld=v==='loading';return `<div class="cl-row">${btn(ld?spin+'Saving…':(p.icon?ic('check'):'')+esc(p.label||'Save changes'),'primary '+st,d+(ld?' aria-busy="true"':''))}${btn('Preview',st,d)}${btn('Delete','danger '+st,d)}</div>`;},
  css:'',a11y:{role:'button (native <button>)',keys:['Enter / Space: activate','Tab: move focus'],notes:'One primary action per view. Loading keeps the button size and sets aria-busy. Disabled buttons are skipped by Tab; explain why the action is unavailable nearby.',wcag:['2.1.1 Keyboard','2.4.7 Focus visible','1.4.3 Contrast']}},
 {id:'C02',name:'Icon buttons',v:V('default:Default','hover:Hover','focus:Focus','active:Pressed','disabled:Disabled'),
  html:v=>{const st=has(v,'hover','focus','active')?'is-'+v:'';const d=v==='disabled'?'disabled':'';return `<div class="cl-row">${[['heart','Like'],['bookmark','Save'],['plus','Add'],['search','Search']].map(([n,l],i)=>`<span class="cl-tipwrap">${btn(ic(n),'icon '+(i===1?'is-pressed ':'')+st,`${d} aria-label="${l}"${i===1?' aria-pressed="true"':''}`)}${i===0&&has(v,'hover','focus')?`<span class="cl-tip" role="tooltip">${l}</span>`:''}</span>`).join('')}</div>`;},
  css:'.cl-tipwrap{position:relative;display:inline-flex}.cl-btn.is-pressed{color:var(--cl-accent);border-color:var(--cl-accent)}.cl-tip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);white-space:nowrap;background:var(--cl-text);color:var(--cl-bg);font-size:12px;padding:5px 8px;border-radius:6px}',
  a11y:{role:'button with aria-label; aria-pressed for toggles',keys:['Enter / Space: activate'],notes:'Every icon button needs an accessible name and a visible tooltip on hover and focus. Hit area at least 44 × 44 px.',wcag:['4.1.2 Name, role, value','2.5.8 Target size']}},
 {id:'C03',name:'Text fields',v:V('default:Empty','hover:Hover','focus:Focus','filled:Filled','error:Error','disabled:Disabled'),
  html:(v,p)=>`<div class="is-${v}" style="max-width:340px">${field(esc(p.label||'Project name'),`<input class="cl-input" ${v==='filled'||v==='error'?'value="A new direction"':''} placeholder="My new app" ${v==='disabled'?'disabled':''} ${v==='error'?'aria-invalid="true"':''}>`,'Give your project a memorable name.',v==='error'?'That name is already used by another project.':'')}</div>`,
  css:'.is-disabled .cl-input{background:transparent}',a11y:{role:'textbox (native <input>) with <label>',keys:['Tab: focus','Type to edit'],notes:'Keep the label visible above the field; placeholder is an example, never the label. Errors sit under the field, name the problem and how to fix it, and set aria-invalid plus aria-describedby.',wcag:['3.3.1 Error identification','3.3.2 Labels or instructions','1.3.1 Info and relationships']}},
 {id:'C04',name:'Text areas',v:V('default:Default','focus:Focus','error:Too long','disabled:Disabled'),
  html:(v,p)=>`<div class="is-${v}" style="max-width:380px">${field(esc(p.label||'Creative brief'),`<textarea class="cl-input" rows="4" ${v==='disabled'?'disabled':''} style="min-height:110px;resize:vertical">${v==='error'?'A calmer way to plan. Clear hierarchy. Room for ideas, references, small discoveries and every direction worth keeping…':'A calmer way to plan. Clear hierarchy.'}</textarea>`,v==='error'?'':'<span>72 / 400 characters</span>',v==='error'?'412 / 400 characters. Shorten by 12.':'')}</div>`,
  css:'textarea.cl-input{display:block}',a11y:{role:'textbox multiline',keys:['Tab: focus','Enter: new line'],notes:'Show a live character count when there is a limit and announce it politely when the limit is passed.',wcag:['3.3.1 Error identification']}},
 {id:'C05',name:'Select menus',v:V('default:Closed','focus:Focus','open:Open','error:Error','disabled:Disabled'),
  html:v=>`<div class="is-${v}" style="max-width:300px;position:relative">${field('Project phase',`<button type="button" class="cl-input cl-select" aria-haspopup="listbox" aria-expanded="${v==='open'}" ${v==='disabled'?'disabled':''}><span>${v==='error'?'Choose a phase':'Making'}</span>${ic('chevron')}</button>${v==='open'?`<ul class="cl-list cl-surface" role="listbox">${['Planning','Making','Review','Shipped'].map((o,i)=>`<li role="option" aria-selected="${i===1}" class="${i===1?'is-sel':''}${i===2?' is-act':''}">${o}${i===1?ic('check'):''}</li>`).join('')}</ul>`:''}`,'',v==='error'?'Choose the phase this project is in.':'')}</div>`,
  css:'.cl-select{justify-content:space-between;cursor:pointer;text-align:left}.cl-list{list-style:none;margin:6px 0 0;padding:6px;position:absolute;left:0;right:0;top:100%;z-index:2}.cl-list li{display:flex;justify-content:space-between;align-items:center;padding:8px 10px;border-radius:var(--cl-radius-sm);font-size:14px}.cl-list .is-act{background:color-mix(in srgb,var(--cl-accent) 12%,transparent)}.cl-list .is-sel{font-weight:700;color:var(--cl-accent)}',
  a11y:{role:'native <select>, or button + listbox',keys:['Space / Enter: open','↑ ↓: move','Enter: choose','Esc: close'],notes:'Prefer the native select. A custom listbox must manage aria-activedescendant and return focus to the trigger on close.',wcag:['2.1.1 Keyboard','4.1.2 Name, role, value']}},
 {id:'C06',name:'Comboboxes',v:V('default:Default','typing:Suggestions','empty:No match','disabled:Disabled'),
  html:v=>`<div class="is-${v==='typing'||v==='empty'?'focus':v}" style="max-width:320px;position:relative">${field('Find a project',`<div class="cl-input">${ic('search')}<input class="cl-bare" role="combobox" aria-expanded="${v==='typing'}" value="${v==='typing'?'Gar':v==='empty'?'Zebra':''}" placeholder="Type to search" ${v==='disabled'?'disabled':''}></div>${v==='typing'?`<ul class="cl-list cl-surface" role="listbox">${['<b>Gar</b>den event','<b>Gar</b>den notes','Spring <b>gar</b>land'].map((o,i)=>`<li role="option" class="${i===0?'is-act':''}">${o}</li>`).join('')}</ul>`:v==='empty'?'<div class="cl-list cl-surface" role="status" style="padding:12px;font-size:13.5px">No projects match “Zebra”. Check the spelling or <a href="#">create one</a>.</div>':''}`)}</div>`,
  css:'.cl-bare{border:0;background:none;outline:0;font:inherit;color:inherit;flex:1;min-width:0}.cl-list{list-style:none;margin:6px 0 0;padding:6px;position:absolute;left:0;right:0;top:100%;z-index:2}.cl-list li{padding:8px 10px;border-radius:var(--cl-radius-sm);font-size:14px}.cl-list .is-act{background:color-mix(in srgb,var(--cl-accent) 12%,transparent)}.cl-list a{color:var(--cl-accent)}',
  a11y:{role:'combobox + listbox',keys:['Type: filter','↓: open / move','Enter: choose','Esc: clear or close'],notes:'Announce the result count in a polite live region; keep focus in the input while moving through options.',wcag:['4.1.3 Status messages','2.1.1 Keyboard']}},
 {id:'C07',name:'Checkboxes',v:V('default:Unchecked','checked:Checked','mixed:Indeterminate','focus:Focus','error:Error','disabled:Disabled'),
  html:v=>{const box=(t,on,extra='')=>`<label class="cl-check ${extra}"><span class="cl-box ${on===true?'on':on==='mixed'?'mixed':''}" role="checkbox" aria-checked="${on}">${on===true?ic('check'):on==='mixed'?'<i></i>':''}</span>${t}</label>`;
   const on=v==='checked'?true:v==='mixed'?'mixed':false;return `<fieldset class="cl-fs ${v==='error'?'is-error':''}"><legend class="cl-label">Notify me about</legend>${box('All updates',on,v==='focus'?'is-focus':'')}${box('Comments',v==='checked'||v==='mixed')}${box('Mentions',v==='checked')}${v==='disabled'?box('Billing (admin only)',false,'is-disabled'):''}${v==='error'?'<p class="cl-msg cl-err">Choose at least one.</p>':''}</fieldset>`;},
  css:'.cl-fs{border:0;margin:0;padding:0;display:grid;gap:10px}.cl-check{display:flex;gap:10px;align-items:center;font-size:14.5px;cursor:pointer}.cl-box{width:20px;height:20px;border:2px solid var(--cl-muted);border-radius:min(var(--cl-radius-sm),6px);display:grid;place-items:center;background:var(--cl-surface);flex:none}.cl-box.on,.cl-box.mixed{background:var(--cl-accent);border-color:var(--cl-accent);color:var(--cl-on-accent)}.cl-box .cl-ic{width:14px;height:14px;stroke-width:3}.cl-box i{width:10px;height:2px;background:currentColor}.cl-check.is-focus .cl-box{outline:2px solid var(--cl-accent);outline-offset:2px}.is-error .cl-box{border-color:var(--cl-danger)}',
  a11y:{role:'native <input type=checkbox> in a <fieldset>',keys:['Space: toggle','Tab: next'],notes:'Group related boxes in a fieldset with a legend. A parent “all” box uses the indeterminate state when some children are checked.',wcag:['1.3.1 Info and relationships','4.1.2 Name, role, value']}},
 {id:'C08',name:'Radio groups',v:V('default:Default','focus:Focus','error:Error','disabled:Disabled'),
  html:v=>`<fieldset class="cl-fs"><legend class="cl-label">Delivery</legend>${['Standard · 3–5 days','Express · next day','Collect in store'].map((t,i)=>`<label class="cl-check ${v==='focus'&&i===0?'is-focus':''} ${v==='disabled'&&i===2?'is-disabled':''}"><span class="cl-radio ${i===0&&v!=='error'?'on':''}" role="radio" aria-checked="${i===0&&v!=='error'}"></span>${t}</label>`).join('')}${v==='error'?'<p class="cl-msg cl-err">Choose a delivery option to continue.</p>':''}</fieldset>`,
  css:'.cl-fs{border:0;margin:0;padding:0;display:grid;gap:10px}.cl-check{display:flex;gap:10px;align-items:center;font-size:14.5px}.cl-radio{width:20px;height:20px;border-radius:50%;border:2px solid var(--cl-muted);background:var(--cl-surface);display:grid;place-items:center;flex:none}.cl-radio.on{border-color:var(--cl-accent)}.cl-radio.on::after{content:"";width:10px;height:10px;border-radius:50%;background:var(--cl-accent)}.cl-check.is-focus .cl-radio{outline:2px solid var(--cl-accent);outline-offset:2px}',
  a11y:{role:'radiogroup of native radios',keys:['↑ ↓ / ← →: move and select','Tab: leave the group'],notes:'Tab enters the group once; arrows move between options. Preselect a sensible default where one exists.',wcag:['2.1.1 Keyboard','1.3.1 Info and relationships']}},
 {id:'C09',name:'Switches',v:V('off:Off','on:On','focus:Focus','disabled:Disabled'),
  html:v=>`<div class="cl-stack">${[['Reduced motion',v==='on'],['Show grid',true],['Autosave',v!=='off']].map(([t,on],i)=>`<label class="cl-switchrow ${v==='focus'&&i===0?'is-focus':''} ${v==='disabled'&&i===2?'is-disabled':''}"><span>${t}</span><span class="cl-switch ${on?'on':''}" role="switch" aria-checked="${on}"><i></i></span></label>`).join('')}</div>`,
  css:'.cl-switchrow{display:flex;justify-content:space-between;align-items:center;gap:20px;max-width:300px;font-size:14.5px}.cl-switch{width:44px;height:26px;border-radius:999px;background:color-mix(in srgb,var(--cl-muted) 35%,transparent);position:relative;transition:background .2s;flex:none}.cl-switch i{position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);transition:transform .2s}.cl-switch.on{background:var(--cl-accent)}.cl-switch.on i{transform:translateX(18px)}.is-focus .cl-switch{outline:2px solid var(--cl-accent);outline-offset:2px}',
  a11y:{role:'switch (button role="switch" or checkbox)',keys:['Space: toggle'],notes:'Use for settings that apply immediately. The label states the setting, not the action.',wcag:['4.1.2 Name, role, value']}},
 {id:'C10',name:'Sliders',v:V('default:Default','focus:Focus','active:Dragging','disabled:Disabled'),
  html:v=>`<div class="is-${v}" style="max-width:340px"><div class="cl-row" style="justify-content:space-between"><span class="cl-label">Spacing</span><output class="cl-chip">${v==='active'?32:24} px</output></div><div class="cl-slider"><span class="cl-track"><i style="width:${v==='active'?71:43}%"></i></span><span class="cl-thumb" role="slider" aria-valuemin="12" aria-valuemax="40" aria-valuenow="${v==='active'?32:24}" style="left:${v==='active'?71:43}%">${v==='active'?'<b>32</b>':''}</span></div><div class="cl-row cl-muted" style="justify-content:space-between;font-size:12px"><span>12</span><span>40</span></div></div>`,
  css:'.cl-slider{position:relative;height:28px;margin:6px 0}.cl-track{position:absolute;top:12px;left:0;right:0;height:4px;border-radius:99px;background:color-mix(in srgb,var(--cl-muted) 30%,transparent)}.cl-track i{display:block;height:100%;border-radius:inherit;background:var(--cl-accent)}.cl-thumb{position:absolute;top:4px;width:20px;height:20px;margin-left:-10px;border-radius:50%;background:var(--cl-surface);border:2px solid var(--cl-accent);box-shadow:0 1px 4px rgba(0,0,0,.2)}.is-focus .cl-thumb{outline:2px solid var(--cl-accent);outline-offset:3px}.is-active .cl-thumb{transform:scale(1.2)}.cl-thumb b{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);background:var(--cl-text);color:var(--cl-bg);font-size:11px;padding:3px 6px;border-radius:5px}',
  a11y:{role:'slider (native <input type=range>)',keys:['← →: step','Page Up / Down: big step','Home / End: limits'],notes:'Always show the current value as text, plus the limits. Provide a number input for exact values.',wcag:['2.1.1 Keyboard','2.5.7 Dragging movements']}},
 {id:'C11',name:'Date pickers',v:V('default:Closed','open:Open','error:Error','disabled:Disabled'),
  html:v=>`<div class="is-${v}" style="max-width:300px;position:relative">${field('Launch date',`<div class="cl-input"><input class="cl-bare" value="${v==='error'?'31/02/2027':'14/11/2026'}" ${v==='disabled'?'disabled':''} aria-invalid="${v==='error'}"><button type="button" class="cl-btn icon" style="min-height:30px;width:30px;box-shadow:none" aria-label="Choose date">${ic('cal')}</button></div>${v==='open'?`<div class="cl-pop cl-surface">${cal(14)}</div>`:''}`,'DD/MM/YYYY',v==='error'?'February has 28 days in 2027. Choose a date up to 28/02.':'')}</div>`,
  css:'.cl-bare{border:0;background:none;outline:0;font:inherit;color:inherit;flex:1;min-width:0}.cl-pop{position:absolute;top:calc(100% - 18px);left:0;padding:12px;z-index:2;width:280px}',
  a11y:{role:'text input + dialog with a grid',keys:['Type the date','Enter / Space on button: open calendar','Arrows: move by day / week','Esc: close'],notes:'Typing must always work; the calendar is a shortcut. Show the expected format.',wcag:['3.3.2 Labels or instructions','2.1.1 Keyboard']}},
 {id:'C12',name:'Calendar grids',v:V('default:Selected day','range:Range','focus:Keyboard focus'),
  html:v=>`<div class="cl-surface" style="padding:14px;max-width:300px">${cal(14,v)}</div>`,
  css:'',a11y:{role:'grid with gridcell buttons',keys:['Arrows: day / week','Page Up / Down: month','Enter: select'],notes:'Mark today and the selection with more than colour (ring and weight). Headings name the days in full for screen readers.',wcag:['1.4.1 Use of colour','2.1.1 Keyboard']}},
 {id:'C13',name:'File uploaders',v:V('default:Empty','hover:Drag over','loading:Uploading','done:Uploaded','error:Error'),
  html:v=>`<div style="max-width:380px" class="cl-stack"><div class="cl-drop ${v==='hover'?'is-over':''}">${ic('upload')}<p><b>Drop files here</b> or <a href="#">browse</a></p><p class="cl-muted" style="font-size:12.5px">PNG, JPG or PDF · up to 25 MB</p></div>${v==='loading'||v==='done'||v==='error'?`<div class="cl-filerow cl-surface ${v==='error'?'is-error':''}">${ic('file')}<div style="flex:1;min-width:0"><b>moodboard-v3.pdf</b><div class="cl-muted" style="font-size:12.5px">${v==='loading'?'4.2 of 9.8 MB · 12 s left':v==='done'?'9.8 MB · Uploaded':'<span class="cl-err">Upload failed. Check your connection and retry.</span>'}</div>${v==='loading'?'<span class="cl-bar"><i style="width:43%"></i></span>':''}</div>${v==='error'?btn('Retry','', 'style="min-height:32px"'):btn(ic('x'),'icon','aria-label="Remove file" style="min-height:32px;width:32px;box-shadow:none"')}</div>`:''}</div>`,
  css:'.cl-drop{border:2px dashed var(--cl-line);border-radius:var(--cl-radius);padding:22px;text-align:center;display:grid;justify-items:center;gap:6px;background:color-mix(in srgb,var(--cl-surface) 60%,transparent)}.cl-drop p{margin:0}.cl-drop a{color:var(--cl-accent)}.cl-drop .cl-ic{width:26px;height:26px;color:var(--cl-accent)}.cl-drop.is-over{border-color:var(--cl-accent);background:color-mix(in srgb,var(--cl-accent) 10%,transparent)}.cl-filerow{display:flex;gap:12px;align-items:center;padding:12px}.cl-filerow.is-error{border-color:var(--cl-danger)}.cl-bar{display:block;height:4px;border-radius:9px;background:color-mix(in srgb,var(--cl-muted) 25%,transparent);margin-top:6px}.cl-bar i{display:block;height:100%;border-radius:inherit;background:var(--cl-accent)}',
  a11y:{role:'native <input type=file> behind a labelled drop zone',keys:['Enter / Space on “browse”: open picker'],notes:'Drag and drop is an extra, never the only way. Announce progress and errors in a live region; state limits before upload.',wcag:['2.5.7 Dragging movements','4.1.3 Status messages']}},
 {id:'C14',name:'Form validation',v:V('default:Untouched','error:Errors','success:Valid'),
  html:v=>`<form class="cl-stack" style="max-width:340px" novalidate>${v==='error'?'<div class="cl-alert cl-surface is-danger" role="alert"><b>2 fields need attention</b><a href="#">Email</a> · <a href="#">Password</a></div>':''}<div class="${v==='error'?'is-error':''}">${field('Email',`<input class="cl-input" value="${v==='default'?'':v==='error'?'india@studio':'india@studio.com'}">`,'',v==='error'?'Enter an email like name@example.com.':'')}</div><div class="${v==='error'?'is-error':''}">${field('Password',`<input class="cl-input" type="password" value="${v==='default'?'':'secret'}">`,v==='success'?'<span style="color:var(--cl-success)">✓ Strong password</span>':'At least 8 characters.',v==='error'?'Use at least 8 characters. 6 entered.':'')}</div>${btn('Create account','primary')}</form>`,
  css:'.cl-alert{display:grid;gap:4px;padding:12px 14px;font-size:13.5px}.cl-alert.is-danger{border-color:var(--cl-danger);border-left:4px solid var(--cl-danger)}.cl-alert a{color:var(--cl-danger)}',
  a11y:{role:'form with error summary (role=alert) and field messages',keys:['Tab through fields','Summary links move focus to each field'],notes:'Validate on submit or blur, not on every keystroke. On submit, show a summary linking to each error and move focus to it.',wcag:['3.3.1 Error identification','3.3.3 Error suggestion']}},
 {id:'C15',name:'Search and filters',v:V('default:Results','loading:Loading','empty:No results'),
  html:v=>`<div class="cl-stack" style="max-width:420px"><div class="cl-input">${ic('search')}<input class="cl-bare" value="${v==='empty'?'neon clay':'glass'}">${v==='loading'?spin:''}</div><div class="cl-row"><span class="cl-chip">Style ${ic('x')}</span><span class="cl-chip">Calm ${ic('x')}</span><a href="#" style="color:var(--cl-accent);font-size:13px">Reset filters</a></div><p class="cl-muted" role="status" style="margin:0;font-size:13px">${v==='loading'?'Searching…':v==='empty'?'No entries match “neon clay” with these filters.':'12 entries match “glass”'}</p></div>`,
  css:'.cl-bare{border:0;background:none;outline:0;font:inherit;color:inherit;flex:1;min-width:0}.cl-chip .cl-ic{width:13px;height:13px}',
  a11y:{role:'search landmark with a labelled input; status region',keys:['Type to search','Tab to filter chips; Enter removes'],notes:'Announce the result count. Each filter chip has a named remove button. Always offer reset.',wcag:['4.1.3 Status messages']}},
 {id:'C16',name:'Breadcrumbs',v:V('default:Default','focus:Focus','long:Truncated'),
  html:v=>`<nav aria-label="Breadcrumb"><ol class="cl-crumbs">${(v==='long'?['Atlas','…','Systems','Garden Notes / organic botanical']:['Atlas','Design systems','Garden Notes']).map((t,i,a)=>`<li>${i<a.length-1?`<a href="#" class="${v==='focus'&&i===1?'is-focus':''}">${t}</a>${ic('right')}`:`<span aria-current="page">${t}</span>`}</li>`).join('')}</ol></nav>`,
  css:'.cl-crumbs{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;align-items:center;gap:4px;font-size:14px}.cl-crumbs li{display:flex;align-items:center;gap:4px}.cl-crumbs a{color:var(--cl-accent);text-decoration:none}.cl-crumbs a.is-focus{outline:2px solid var(--cl-accent);outline-offset:2px;border-radius:3px}.cl-crumbs .cl-ic{width:14px;height:14px;color:var(--cl-muted)}.cl-crumbs [aria-current]{font-weight:600;max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}',
  a11y:{role:'nav aria-label="Breadcrumb" with an ordered list',keys:['Tab: links'],notes:'The current page is the last item, not a link, with aria-current="page".',wcag:['2.4.8 Location']}},
 {id:'C17',name:'Tab groups',v:V('default:Default','focus:Focus','disabled:Disabled tab'),
  html:v=>`<div><div class="cl-tabs" role="tablist">${['Overview','Typography','Motion','Exports'].map((t,i)=>`<button role="tab" aria-selected="${i===0}" class="cl-tab ${i===0?'on':''} ${v==='focus'&&i===1?'is-focus':''}" ${v==='disabled'&&i===3?'disabled':''}>${t}</button>`).join('')}</div><div class="cl-panel" role="tabpanel">A calm palette, a serif for headings and a single accent. Motion stays under 300 ms.</div></div>`,
  css:'.cl-tabs{display:flex;gap:4px;border-bottom:max(1px,var(--cl-bw)) solid var(--cl-line)}.cl-tab{font:600 14px var(--cl-font);color:var(--cl-muted);background:none;border:0;padding:10px 14px;border-bottom:2px solid transparent;margin-bottom:-1px;cursor:pointer}.cl-tab.on{color:var(--cl-text);border-color:var(--cl-accent)}.cl-tab.is-focus{outline:2px solid var(--cl-accent);outline-offset:-2px;border-radius:4px}.cl-tab[disabled]{opacity:.4}.cl-panel{padding:14px 2px;font-size:14px;color:var(--cl-muted);max-width:420px}',
  a11y:{role:'tablist / tab / tabpanel',keys:['← →: move between tabs','Home / End: first / last','Tab: into the panel'],notes:'Only the selected tab is in the Tab order (roving tabindex). Panels are labelled by their tab.',wcag:['2.1.1 Keyboard','4.1.2 Name, role, value']}},
 {id:'C18',name:'Side navigation',v:V('default:Expanded','collapsed:Collapsed','focus:Focus'),
  html:v=>{const c=v==='collapsed';return `<nav class="cl-side cl-surface ${c?'is-c':''}" aria-label="Workspace">${[['home','Home',1],['grid','Projects'],['folder','Library'],['bell','Updates'],['user','Account']].map(([n,l,on],i)=>`<a href="#" class="${on?'on':''} ${v==='focus'&&i===2?'is-focus':''}" ${on?'aria-current="page"':''} ${c?`aria-label="${l}"`:''}>${ic(n)}${c?'':`<span>${l}</span>`}${i===3&&!c?'<b class="cl-count">3</b>':''}</a>`).join('')}</nav>`;},
  css:'.cl-side{display:grid;gap:2px;padding:8px;width:220px}.cl-side.is-c{width:60px}.cl-side a{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:var(--cl-radius-sm);color:var(--cl-muted);text-decoration:none;font-size:14px;font-weight:600}.cl-side a.on{background:color-mix(in srgb,var(--cl-accent) 14%,transparent);color:var(--cl-accent)}.cl-side a.is-focus{outline:2px solid var(--cl-accent);outline-offset:-2px}.cl-count{margin-left:auto;font-size:11px;background:var(--cl-accent);color:var(--cl-on-accent);border-radius:99px;padding:1px 7px}',
  a11y:{role:'nav landmark with links; aria-current on the active page',keys:['Tab: links'],notes:'In the collapsed state every icon keeps an accessible name and a tooltip.',wcag:['2.4.8 Location','1.1.1 Non-text content']}},
 {id:'C19',name:'Bottom navigation',v:V('default:Default','badge:With badge','focus:Focus'),
  html:v=>`<nav class="cl-bottom cl-surface" aria-label="Main">${[['home','Home'],['search','Search'],['bookmark','Saved'],['user','You']].map(([n,l],i)=>`<a href="#" class="${i===0?'on':''} ${v==='focus'&&i===2?'is-focus':''}" ${i===0?'aria-current="page"':''}><span class="cl-bi">${ic(n)}${v==='badge'&&i===2?'<b>4</b>':''}</span>${l}</a>`).join('')}</nav>`,
  css:'.cl-bottom{display:grid;grid-template-columns:repeat(4,1fr);padding:6px;width:320px}.cl-bottom a{display:grid;justify-items:center;gap:3px;padding:8px 4px;font-size:11.5px;font-weight:600;color:var(--cl-muted);text-decoration:none;border-radius:var(--cl-radius-sm)}.cl-bottom a.on{color:var(--cl-accent)}.cl-bottom a.is-focus{outline:2px solid var(--cl-accent);outline-offset:-2px}.cl-bi{position:relative;display:inline-flex}.cl-bi b{position:absolute;top:-4px;right:-9px;font-size:10px;background:var(--cl-danger);color:#fff;border-radius:99px;padding:0 5px;line-height:15px}',
  a11y:{role:'nav with 3–5 labelled links',keys:['Tab: links'],notes:'Icon and label together; never more than five destinations. Badges include text such as “4 new”.',wcag:['2.5.8 Target size','1.4.1 Use of colour']}},
 {id:'C20',name:'Command palettes',v:V('default:Recent','typing:Results','empty:No match'),
  html:v=>`<div class="cl-cmd cl-surface" role="dialog" aria-label="Command palette"><div class="cl-cmdin">${ic('search')}<input class="cl-bare" value="${v==='typing'?'new':v==='empty'?'qzx':''}" placeholder="Type a command or search"><kbd>esc</kbd></div>${v==='empty'?'<p class="cl-muted" style="padding:18px;margin:0;font-size:13.5px">No commands match “qzx”.</p>':`<ul role="listbox">${(v==='typing'?[['plus','<b>New</b> project','⌘N'],['file','<b>New</b> brief','⌘B'],['grid','Open <b>new</b>est board','']]:[['grid','Open Garden Notes',''],['file','Export design brief','⌘E'],['user','Switch account','']]).map(([n,l,k],i)=>`<li role="option" class="${i===0?'is-act':''}">${ic(n)}<span>${l}</span>${k?`<kbd>${k}</kbd>`:''}</li>`).join('')}</ul>`}</div>`,
  css:'.cl-bare{border:0;background:none;outline:0;font:inherit;color:inherit;flex:1;min-width:0}.cl-cmd{width:380px;overflow:hidden}.cl-cmdin{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--cl-line)}.cl-cmd ul{list-style:none;margin:0;padding:6px}.cl-cmd li{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:var(--cl-radius-sm);font-size:14px}.cl-cmd li span{flex:1}.cl-cmd li.is-act{background:color-mix(in srgb,var(--cl-accent) 13%,transparent)}.cl-cmd kbd{font:11px ui-monospace,monospace;border:1px solid var(--cl-line);border-radius:5px;padding:1px 5px;color:var(--cl-muted)}',
  a11y:{role:'dialog containing a combobox and listbox',keys:['⌘K / Ctrl+K: open','↑ ↓: move','Enter: run','Esc: close'],notes:'Trap focus inside while open and return it to the trigger on close. Show shortcuts as text.',wcag:['2.1.2 No keyboard trap','2.4.3 Focus order']}},
 {id:'C21',name:'Popovers',v:V('default:Closed','open:Open'),
  html:v=>`<div style="position:relative;padding-bottom:${v==='open'?150:0}px">${btn('Share'+ic('chevron'),'', `aria-expanded="${v==='open'}" aria-haspopup="dialog"`)}${v==='open'?`<div class="cl-popover cl-surface" role="dialog" aria-label="Share"><b>Share Garden Notes</b><div class="cl-input" style="margin:10px 0;font-size:13px">atlas.link/g-notes</div>${btn('Copy link','primary','style="min-height:34px"')}</div>`:''}</div>`,
  css:'.cl-popover{position:absolute;top:calc(var(--cl-h) + 10px);left:0;width:250px;padding:14px;z-index:2;font-size:14px}.cl-popover::before{content:"";position:absolute;top:-6px;left:22px;width:10px;height:10px;background:var(--cl-surface);border-left:var(--cl-bw) solid var(--cl-line);border-top:var(--cl-bw) solid var(--cl-line);transform:rotate(45deg)}',
  a11y:{role:'button with aria-expanded controlling a non-modal dialog',keys:['Enter: open','Esc: close and return focus','Tab: through content'],notes:'Close on Esc and outside click; keep it anchored and inside the viewport.',wcag:['1.4.13 Content on hover or focus']}},
 {id:'C22',name:'Tooltips',v:V('default:Hidden','hover:Hover','focus:Focus'),
  html:v=>`<div style="padding-top:${v==='default'?0:44}px;position:relative;display:inline-block">${btn(ic('info')+'Effort','',v==='focus'?'class="is-focus"':'')}${v!=='default'?'<span class="cl-tooltip" role="tooltip">How long this takes to build</span>':''}</div>`,
  css:'.cl-tooltip{position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:nowrap;background:var(--cl-text);color:var(--cl-bg);font-size:12.5px;padding:6px 9px;border-radius:6px}.cl-tooltip::after{content:"";position:absolute;bottom:-4px;left:50%;margin-left:-4px;border:4px solid transparent;border-top-color:var(--cl-text);border-bottom:0}',
  a11y:{role:'tooltip referenced by aria-describedby',keys:['Shown on focus as well as hover','Esc: dismiss'],notes:'Tooltips hold supplementary text only, never essential instructions. They stay open while hovered.',wcag:['1.4.13 Content on hover or focus']}},
 {id:'C23',name:'Dialogs',v:V('default:Confirm','danger:Destructive','loading:Working'),
  html:(v,p)=>`<div class="cl-scrim"><div class="cl-dialog cl-surface" role="dialog" aria-modal="true" aria-labelledby="dlg"><div class="cl-row" style="justify-content:space-between"><h3 class="cl-h" id="dlg">${v==='danger'?'Delete Garden Notes?':esc(p.label||'Save this direction?')}</h3>${btn(ic('x'),'icon','aria-label="Close" style="min-height:32px;width:32px;box-shadow:none"')}</div><p class="cl-muted" style="margin:10px 0 18px;font-size:14px">${v==='danger'?'The board and its 24 references will be removed. You can undo for 30 seconds.':'It will be added to your project with its colours, type and motion.'}</p><div class="cl-row" style="justify-content:flex-end">${btn('Cancel')}${btn(v==='loading'?spin+'Saving…':v==='danger'?'Delete board':'Save direction',v==='danger'?'danger':'primary')}</div></div></div>`,
  css:'.cl-scrim{padding:22px;background:color-mix(in srgb,#000 35%,transparent);border-radius:var(--cl-radius)}.cl-dialog{max-width:380px;padding:20px}',
  a11y:{role:'dialog aria-modal="true" (native <dialog>)',keys:['Esc: close','Tab: cycles inside','Focus returns to the trigger'],notes:'Move focus to the first useful control. Name the action on the button (“Delete board”), not “OK”.',wcag:['2.4.3 Focus order','2.1.2 No keyboard trap']}},
 {id:'C24',name:'Drawers and sheets',v:V('default:Side drawer','sheet:Bottom sheet'),
  html:v=>v==='sheet'?`<div class="cl-device"><div class="cl-sheet cl-surface"><span class="cl-grab"></span><b>Filters</b><div class="cl-row" style="margin:12px 0"><span class="cl-chip">Glass</span><span class="cl-chip">Paper</span><span class="cl-chip">Clay</span></div>${btn('Show 12 results','primary','style="width:100%"')}</div></div>`:`<div class="cl-device wide"><div class="cl-drawer cl-surface"><div class="cl-row" style="justify-content:space-between"><b>Project settings</b>${btn(ic('x'),'icon','aria-label="Close" style="min-height:30px;width:30px;box-shadow:none"')}</div><div class="cl-stack" style="margin-top:14px;font-size:14px"><span>Name</span><span class="cl-muted">Members</span><span class="cl-muted">Exports</span></div></div></div>`,
  css:'.cl-device{position:relative;width:240px;height:230px;border-radius:22px;background:color-mix(in srgb,var(--cl-muted) 18%,var(--cl-bg));overflow:hidden;border:1px solid var(--cl-line)}.cl-device.wide{width:360px;border-radius:12px}.cl-sheet{position:absolute;left:0;right:0;bottom:0;padding:12px 16px 16px;border-radius:var(--cl-radius) var(--cl-radius) 0 0;font-size:14px}.cl-grab{display:block;width:36px;height:4px;border-radius:9px;background:var(--cl-line);margin:0 auto 10px}.cl-drawer{position:absolute;top:0;right:0;bottom:0;width:200px;padding:16px;border-radius:0}',
  a11y:{role:'dialog anchored to an edge',keys:['Esc: close','Focus moves in and returns'],notes:'Sheets can be dragged, but always also have a close button. Keep the page behind inert.',wcag:['2.5.7 Dragging movements','2.4.3 Focus order']}},
 {id:'C25',name:'Accordions',v:V('default:Collapsed','open:Expanded','focus:Focus'),
  html:v=>`<div class="cl-acc cl-surface">${['What is a direction?','Can I export tokens?','Who can see my projects?'].map((q,i)=>`<div class="cl-accitem"><button type="button" aria-expanded="${v==='open'&&i===0}" class="${v==='focus'&&i===1?'is-focus':''}">${q}${ic('chevron')}</button>${v==='open'&&i===0?'<p>A saved combination of style, type, colour and motion that you can reuse across a project.</p>':''}</div>`).join('')}</div>`,
  css:'.cl-acc{max-width:400px;overflow:hidden}.cl-accitem+.cl-accitem{border-top:1px solid var(--cl-line)}.cl-accitem button{all:unset;box-sizing:border-box;width:100%;display:flex;justify-content:space-between;align-items:center;padding:14px 16px;font-weight:600;font-size:14.5px;cursor:pointer}.cl-accitem button.is-focus{outline:2px solid var(--cl-accent);outline-offset:-2px}.cl-accitem [aria-expanded=true] .cl-ic{transform:rotate(180deg)}.cl-accitem p{margin:0;padding:0 16px 14px;color:var(--cl-muted);font-size:14px}',
  a11y:{role:'buttons with aria-expanded controlling regions (or <details>)',keys:['Enter / Space: toggle','Tab: next header'],notes:'Headers are real buttons inside headings. Don’t hide content users need to compare.',wcag:['4.1.2 Name, role, value']}},
 {id:'C26',name:'Toasts',v:V('default:Info','success:Success','error:Error + undo','loading:Working'),
  html:v=>{const m={default:['info','Link copied to clipboard.'],success:['check','Direction saved to Garden Notes.'],error:['warn','Board deleted.'],loading:['','Exporting brief…']}[v];return `<div class="cl-toast cl-surface is-${v}" role="${v==='error'?'alert':'status'}">${v==='loading'?spin:ic(m[0])}<span>${m[1]}</span>${v==='error'?'<button class="cl-link">Undo</button>':''}${btn(ic('x'),'icon','aria-label="Dismiss" style="min-height:28px;width:28px;box-shadow:none;border:0"')}</div>`;},
  css:'.cl-toast{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 14px;max-width:380px;font-size:14px}.cl-toast span{flex:1}.cl-toast.is-success>.cl-ic{color:var(--cl-success)}.cl-toast.is-error>.cl-ic{color:var(--cl-danger)}.cl-toast.is-default>.cl-ic{color:var(--cl-accent)}.cl-link{all:unset;color:var(--cl-accent);font-weight:700;cursor:pointer}',
  a11y:{role:'status (polite) or alert (assertive) live region',keys:['Undo reachable by keyboard','Esc: dismiss'],notes:'Keep toasts on screen long enough to read (≥ 5 s plus 1 s per 30 characters) and pause on hover/focus. Never put the only path to an action in a toast.',wcag:['2.2.1 Timing adjustable','4.1.3 Status messages']}},
 {id:'C27',name:'Alerts and banners',v:V('default:Info','warn:Warning','error:Error','success:Success'),
  html:v=>{const m={default:['info','Heads up','Fonts load from Google Fonts. Bundled families work offline.','accent'],warn:['warn','Storage nearly full','You have used 92% of local storage. Export a backup.','warn'],error:['warn','Export failed','The PDF could not be created. Try again or download PNG.','danger'],success:['check','Backup complete','24 projects saved to atlas-backup.json.','success']}[v];return `<div class="cl-banner cl-surface" style="--tone:var(--cl-${m[3]})" role="${v==='error'?'alert':'status'}">${ic(m[0])}<div><b>${m[1]}</b><p>${m[2]}</p></div>${v==='error'?btn('Try again','', 'style="min-height:32px"'):''}</div>`;},
  css:'.cl-banner{display:flex;gap:12px;align-items:flex-start;padding:14px 16px;max-width:460px;border-left:4px solid var(--tone);font-size:14px}.cl-banner>.cl-ic{color:var(--tone);margin-top:1px}.cl-banner div{flex:1}.cl-banner p{margin:2px 0 0;color:var(--cl-muted)}',
  a11y:{role:'status or alert region',keys:['Recovery action is a real button'],notes:'Severity is shown by icon, title and colour together. Say what happened and what to do next.',wcag:['1.4.1 Use of colour','3.3.3 Error suggestion']}},
 {id:'C28',name:'Badges and tags',v:V('default:Status','tags:Removable tags','focus:Focus'),
  html:v=>v==='default'?`<div class="cl-row">${[['Draft','muted'],['In review','warn'],['Approved','success'],['Blocked','danger'],['New','accent']].map(([t,c])=>`<span class="cl-badge" style="--tone:var(--cl-${c})"><i></i>${t}</span>`).join('')}</div>`:`<div class="cl-row">${['Glass','Botanical','Calm'].map((t,i)=>`<span class="cl-chip">${t}<button class="cl-x ${v==='focus'&&i===1?'is-focus':''}" aria-label="Remove ${t}">${ic('x')}</button></span>`).join('')}</div>`,
  css:'.cl-badge{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;font-size:12.5px;font-weight:700;color:var(--tone);background:color-mix(in srgb,var(--tone) 12%,transparent)}.cl-badge i{width:7px;height:7px;border-radius:50%;background:currentColor}.cl-x{all:unset;display:grid;place-items:center;width:18px;height:18px;border-radius:50%;cursor:pointer}.cl-x .cl-ic{width:12px;height:12px}.cl-x.is-focus{outline:2px solid var(--cl-accent)}',
  a11y:{role:'text; remove buttons with names',keys:['Tab: remove buttons','Enter: remove'],notes:'The word carries the meaning; colour reinforces it. Remove buttons say what they remove.',wcag:['1.4.1 Use of colour','4.1.2 Name, role, value']}},
 {id:'C29',name:'Avatars and groups',v:V('default:Group','status:With status','single:Single'),
  html:v=>{const people=[['IR','#f59e0b','India Rose'],['MK','#10b981','Mika K.'],['JL','#6366f1','Jo L.'],['AS','#ec4899','Ana S.']];return v==='single'?`<div class="cl-row"><span class="cl-av lg" style="--c:#6366f1">IR</span><div><b>India Rose</b><div class="cl-muted" style="font-size:13px">Creative director</div></div></div>`:`<div class="cl-row"><div class="cl-avs">${people.map(([i,c,n],k)=>`<span class="cl-av" style="--c:${c}" title="${n}">${i}${v==='status'&&k<2?'<b class="on"></b>':''}</span>`).join('')}<span class="cl-av more">+5</span></div><span class="cl-muted" style="font-size:13px">9 people on this board</span></div>`;},
  css:'.cl-avs{display:flex}.cl-av{position:relative;width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font-size:12.5px;font-weight:700;color:#fff;background:var(--c);border:2px solid var(--cl-surface)}.cl-avs .cl-av+.cl-av{margin-left:-10px}.cl-av.more{background:var(--cl-surface);color:var(--cl-text);border-color:var(--cl-line)}.cl-av.lg{width:48px;height:48px;font-size:15px}.cl-av b{position:absolute;right:-1px;bottom:-1px;width:11px;height:11px;border-radius:50%;border:2px solid var(--cl-surface);background:var(--cl-success)}',
  a11y:{role:'img with alt (or initials + name text)',keys:['—'],notes:'A group states the total in text (“9 people”). Status dots have a text equivalent.',wcag:['1.1.1 Non-text content']}},
 {id:'C30',name:'Content cards',v:V('default:Default','hover:Hover','focus:Focus','selected:Selected','loading:Loading'),
  html:(v,p)=>v==='loading'?`<div class="cl-card cl-surface" aria-busy="true"><span class="cl-skel" style="height:120px"></span><span class="cl-skel" style="width:60%"></span><span class="cl-skel" style="width:85%"></span></div>`:`<article class="cl-card cl-surface is-${v}"><div class="cl-cardimg"></div><span class="cl-badge" style="--tone:var(--cl-success)"><i></i>Ready</span><h3 class="cl-h">${esc(p.label||'Garden Notes')}</h3><p class="cl-muted" style="margin:0;font-size:13.5px">Sage, ivory and warm botanical imagery.</p><a href="#" class="cl-cardlink">Open board ${ic('right')}</a></article>`,
  css:'.cl-card{width:260px;padding:12px;display:grid;gap:10px;transition:transform .2s,box-shadow .2s}.cl-card.is-hover{transform:translateY(-3px)}.cl-card.is-focus{outline:2px solid var(--cl-accent);outline-offset:3px}.cl-card.is-selected{border-color:var(--cl-accent);box-shadow:0 0 0 2px var(--cl-accent)}.cl-cardimg{height:120px;border-radius:var(--cl-radius-sm);background:linear-gradient(135deg,color-mix(in srgb,var(--cl-accent) 40%,var(--cl-bg)),color-mix(in srgb,var(--cl-success) 30%,var(--cl-bg)))}.cl-cardlink{display:inline-flex;align-items:center;gap:4px;color:var(--cl-accent);font-weight:700;font-size:14px;text-decoration:none}.cl-cardlink .cl-ic{width:15px;height:15px}.cl-badge{display:inline-flex;align-items:center;gap:6px;width:fit-content;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:700;color:var(--tone);background:color-mix(in srgb,var(--tone) 12%,transparent)}.cl-badge i{width:7px;height:7px;border-radius:50%;background:currentColor}.cl-skel{display:block;height:14px;border-radius:6px;background:linear-gradient(90deg,color-mix(in srgb,var(--cl-muted) 18%,transparent) 30%,color-mix(in srgb,var(--cl-muted) 30%,transparent) 50%,color-mix(in srgb,var(--cl-muted) 18%,transparent) 70%);background-size:300% 100%;animation:cl-shimmer 1.4s linear infinite}@keyframes cl-shimmer{to{background-position:-150% 0}}',
  a11y:{role:'article with one primary link',keys:['Tab: the card link'],notes:'One clear action per card. If the whole card is clickable, stretch the single link rather than nesting interactive elements.',wcag:['2.4.4 Link purpose']}},
 {id:'C31',name:'Data tables',v:V('default:Default','sorted:Sorted','selected:Row selected','empty:Empty'),
  html:v=>`<div class="cl-surface" style="overflow:auto;max-width:520px"><table class="cl-table"><thead><tr>${v==='selected'?'<th><span class="cl-box on" style="width:16px;height:16px"></span></th>':''}<th aria-sort="${v==='sorted'?'descending':'none'}">Project ${v==='sorted'?'↓':''}</th><th>Owner</th><th class="num">Refs</th><th>Status</th></tr></thead><tbody>${v==='empty'?'<tr><td colspan="4" class="cl-muted" style="text-align:center;padding:26px">No projects yet. Create one to start collecting references.</td></tr>':[['Garden Notes','India',24,'Approved','success'],['Aurora launch','Mika',12,'In review','warn'],['Clay toys','Jo',7,'Draft','muted']].map((r,i)=>`<tr class="${v==='selected'&&i===1?'is-sel':''}">${v==='selected'?`<td><span class="cl-box ${i===1?'on':''}" style="width:16px;height:16px"></span></td>`:''}<td><b>${r[0]}</b></td><td>${r[1]}</td><td class="num">${r[2]}</td><td><span class="cl-badge" style="--tone:var(--cl-${r[4]})"><i></i>${r[3]}</span></td></tr>`).join('')}</tbody></table></div>`,
  css:'.cl-table{border-collapse:collapse;width:100%;font-size:13.5px}.cl-table th{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--cl-muted);font-weight:700;padding:10px 12px;border-bottom:1px solid var(--cl-line);white-space:nowrap}.cl-table td{padding:10px 12px;border-bottom:1px solid var(--cl-line)}.cl-table tr:last-child td{border-bottom:0}.cl-table .num{text-align:right;font-variant-numeric:tabular-nums}.cl-table tr.is-sel{background:color-mix(in srgb,var(--cl-accent) 10%,transparent)}.cl-badge{display:inline-flex;align-items:center;gap:6px;padding:2px 9px;border-radius:999px;font-size:12px;font-weight:700;color:var(--tone);background:color-mix(in srgb,var(--tone) 12%,transparent)}.cl-badge i{width:6px;height:6px;border-radius:50%;background:currentColor}.cl-box{display:inline-grid;border:2px solid var(--cl-muted);border-radius:4px;vertical-align:middle}.cl-box.on{background:var(--cl-accent);border-color:var(--cl-accent)}',
  a11y:{role:'table with th scope and aria-sort',keys:['Tab: sortable headers (buttons)','Enter: sort'],notes:'Numbers align right with tabular figures. Sort state is in aria-sort and visible. Empty tables say why and what to do.',wcag:['1.3.1 Info and relationships']}},
 {id:'C32',name:'Pagination',v:V('default:Middle page','first:First page','focus:Focus'),
  html:v=>{const cur=v==='first'?1:4;return `<nav aria-label="Pages" class="cl-pages">${btn(ic('left')+'Previous','',cur===1?'disabled':'')}${[1,2,3,4,5,'…',12].map(n=>n==='…'?'<span class="cl-muted">…</span>':`<a href="#" class="${n===cur?'on':''} ${v==='focus'&&n===5?'is-focus':''}" ${n===cur?'aria-current="page"':''}>${n}</a>`).join('')}${btn('Next'+ic('right'))}</nav>`;},
  css:'.cl-pages{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.cl-pages a{display:grid;place-items:center;min-width:38px;height:38px;border-radius:var(--cl-radius-sm);text-decoration:none;color:var(--cl-text);font-weight:600;font-size:14px}.cl-pages a.on{background:var(--cl-accent);color:var(--cl-on-accent)}.cl-pages a.is-focus{outline:2px solid var(--cl-accent);outline-offset:2px}.cl-pages .cl-btn{min-height:38px}',
  a11y:{role:'nav aria-label="Pages"; aria-current on the current page',keys:['Tab: links'],notes:'Previous is disabled on page 1, not hidden, so the layout stays still.',wcag:['2.4.8 Location']}},
 {id:'C33',name:'Tree views',v:V('default:Collapsed','open:Expanded','focus:Focus'),
  html:v=>{const o=v!=='default';return `<ul class="cl-tree cl-surface" role="tree"><li role="treeitem" aria-expanded="${o}"><span>${ic(o?'chevron':'right')}${ic('folder')}Projects</span>${o?`<ul role="group"><li role="treeitem" aria-expanded="true"><span>${ic('chevron')}${ic('folder')}Garden Notes</span><ul role="group"><li role="treeitem" class="${v==='focus'?'is-focus':''}"><span class="leaf">${ic('file')}brief.pdf</span></li><li role="treeitem" aria-selected="true" class="sel"><span class="leaf">${ic('file')}palette.json</span></li></ul></li><li role="treeitem"><span>${ic('right')}${ic('folder')}Aurora launch</span></li></ul>`:''}</li><li role="treeitem"><span>${ic('right')}${ic('folder')}Archive</span></li></ul>`;},
  css:'.cl-tree,.cl-tree ul{list-style:none;margin:0;padding:0}.cl-tree{padding:8px;width:280px;font-size:14px}.cl-tree ul{padding-left:18px}.cl-tree span{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:var(--cl-radius-sm)}.cl-tree span .cl-ic{width:16px;height:16px;color:var(--cl-muted)}.cl-tree .leaf{padding-left:30px}.cl-tree .sel>span{background:color-mix(in srgb,var(--cl-accent) 13%,transparent);color:var(--cl-accent);font-weight:600}.cl-tree .is-focus>span{outline:2px solid var(--cl-accent);outline-offset:-2px}',
  a11y:{role:'tree / treeitem / group',keys:['↑ ↓: move','→: expand / enter','←: collapse / parent','Enter: open'],notes:'One tab stop for the whole tree; arrows do the rest. Expanded state in aria-expanded.',wcag:['2.1.1 Keyboard']}},
 {id:'C34',name:'Steppers',v:V('default:Step 2','done:Complete','error:Error'),
  html:v=>{const steps=['Brief','Direction','Assets','Review'];const cur=v==='done'?4:v==='error'?2:1;return `<ol class="cl-steps">${steps.map((s,i)=>{const st=i<cur?'done':i===cur?(v==='error'?'err':'cur'):'';return `<li class="${st}" ${st==='cur'?'aria-current="step"':''}><span>${st==='done'?ic('check'):st==='err'?'!':i+1}</span>${s}${st==='err'?'<small>Pick at least one style</small>':''}</li>`;}).join('')}</ol>`;},
  css:'.cl-steps{list-style:none;margin:0;padding:0;display:flex;gap:6px;max-width:520px}.cl-steps li{flex:1;display:grid;justify-items:center;gap:6px;text-align:center;font-size:13px;font-weight:600;color:var(--cl-muted);position:relative}.cl-steps li:not(:last-child)::after{content:"";position:absolute;top:15px;left:calc(50% + 20px);right:calc(-50% + 20px);height:2px;background:var(--cl-line)}.cl-steps li.done:not(:last-child)::after{background:var(--cl-accent)}.cl-steps span{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;border:2px solid var(--cl-line);background:var(--cl-surface)}.cl-steps .done span{background:var(--cl-accent);border-color:var(--cl-accent);color:var(--cl-on-accent)}.cl-steps .cur{color:var(--cl-text)}.cl-steps .cur span{border-color:var(--cl-accent);color:var(--cl-accent)}.cl-steps .err{color:var(--cl-danger)}.cl-steps .err span{border-color:var(--cl-danger)}.cl-steps small{font-weight:500;font-size:11.5px}.cl-steps .cl-ic{width:16px;height:16px;stroke-width:2.6}',
  a11y:{role:'ordered list; aria-current="step"',keys:['Completed steps are links back'],notes:'Show the step number and name in text (“Step 2 of 4: Direction”).',wcag:['2.4.8 Location','1.4.1 Use of colour']}},
 {id:'C35',name:'Progress indicators',v:V('default:Determinate','indeterminate:Indeterminate','done:Complete','error:Failed'),
  html:v=>`<div class="cl-stack" style="max-width:360px"><div class="cl-row" style="justify-content:space-between;font-size:14px"><b>Exporting moodboard</b><span class="cl-muted">${{default:'40%',indeterminate:'Preparing…',done:'Done',error:'Failed'}[v]}</span></div><div class="cl-prog ${v}" role="progressbar" ${v==='default'?'aria-valuenow="40" aria-valuemin="0" aria-valuemax="100"':''}><i style="width:${{default:40,indeterminate:35,done:100,error:62}[v]}%"></i></div>${v==='error'?'<p class="cl-msg cl-err">The PDF stopped at page 8. Retry or export PNG.</p>':''}<div class="cl-row"><span class="cl-ring" style="--p:${v==='done'?100:40}"><b>${v==='done'?'✓':'40%'}</b></span><span class="cl-muted" style="font-size:13px">Circular variant</span></div></div>`,
  css:'.cl-prog{height:8px;border-radius:99px;background:color-mix(in srgb,var(--cl-muted) 22%,transparent);overflow:hidden}.cl-prog i{display:block;height:100%;border-radius:inherit;background:var(--cl-accent)}.cl-prog.done i{background:var(--cl-success)}.cl-prog.error i{background:var(--cl-danger)}.cl-prog.indeterminate i{animation:cl-indet 1.3s ease-in-out infinite}@keyframes cl-indet{0%{transform:translateX(-100%)}100%{transform:translateX(300%)}}.cl-ring{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--cl-accent) calc(var(--p)*1%),color-mix(in srgb,var(--cl-muted) 22%,transparent) 0)}.cl-ring b{width:34px;height:34px;border-radius:50%;background:var(--cl-bg);display:grid;place-items:center;font-size:11px}',
  a11y:{role:'progressbar with aria-valuenow (omit for indeterminate)',keys:['—'],notes:'Name the task, show the number, and announce completion or failure in a live region.',wcag:['4.1.3 Status messages']}},
 {id:'C36',name:'Skeleton loading',v:V('default:Loading','loaded:Loaded'),
  html:v=>v==='default'?`<div class="cl-surface" style="padding:14px;width:320px;display:grid;gap:10px" aria-busy="true" aria-label="Loading projects"><div class="cl-row"><span class="cl-skel" style="width:40px;height:40px;border-radius:50%"></span><div style="flex:1;display:grid;gap:8px"><span class="cl-skel" style="width:60%"></span><span class="cl-skel" style="width:40%"></span></div></div><span class="cl-skel" style="height:90px"></span><p class="cl-muted" style="margin:0;font-size:12.5px">Loading projects…</p></div>`:`<div class="cl-surface" style="padding:14px;width:320px;display:grid;gap:10px"><div class="cl-row"><span class="cl-av" style="--c:#6366f1;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:700;background:var(--c)">IR</span><div><b>Garden Notes</b><div class="cl-muted" style="font-size:13px">Updated 2 h ago</div></div></div><div style="height:90px;border-radius:var(--cl-radius-sm);background:linear-gradient(135deg,color-mix(in srgb,var(--cl-accent) 40%,var(--cl-bg)),color-mix(in srgb,var(--cl-success) 30%,var(--cl-bg)))"></div></div>`,
  css:'.cl-skel{display:block;height:12px;border-radius:6px;background:linear-gradient(90deg,color-mix(in srgb,var(--cl-muted) 18%,transparent) 30%,color-mix(in srgb,var(--cl-muted) 30%,transparent) 50%,color-mix(in srgb,var(--cl-muted) 18%,transparent) 70%);background-size:300% 100%;animation:cl-shimmer 1.4s linear infinite}@keyframes cl-shimmer{to{background-position:-150% 0}}',
  a11y:{role:'container with aria-busy and a text label',keys:['—'],notes:'Match the final layout so nothing jumps. Stop the shimmer for reduced motion; keep a text loading message.',wcag:['2.3.3 Animation from interactions','4.1.3 Status messages']}},
 {id:'C37',name:'Empty states',v:V('default:First use','search:No results','error:Error'),
  html:v=>{const m={default:['folder','No projects yet','Create a project, then add styles, motion and references to it.','Create project'],search:['search','Nothing matches “neon clay”','Try a broader word, or clear the Calm filter.','Clear filters'],error:['warn','We couldn’t load your boards','Check your connection, then try again. Your work is saved on this device.','Try again']}[v];return `<div class="cl-empty cl-surface"><span class="cl-emico">${ic(m[0])}</span><h3 class="cl-h">${m[1]}</h3><p class="cl-muted">${m[2]}</p>${btn(m[3],v==='default'?'primary':'')}</div>`;},
  css:'.cl-empty{display:grid;justify-items:center;text-align:center;gap:8px;padding:28px 24px;width:340px}.cl-empty p{margin:0 0 8px;font-size:14px}.cl-emico{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--cl-accent) 12%,transparent);color:var(--cl-accent)}.cl-emico .cl-ic{width:24px;height:24px}',
  a11y:{role:'region with heading',keys:['Next action is a real button'],notes:'Explain why it is empty and give the next step. Errors say what to do, without blame.',wcag:['3.3.3 Error suggestion']}},
 {id:'C38',name:'Carousels',v:V('default:Default','focus:Focus','last:Last slide'),
  html:v=>{const cur=v==='last'?3:1;return `<section class="cl-car" aria-roledescription="carousel" aria-label="Featured styles"><div class="cl-slides">${['Glass','Clay','Aurora','Zine'].map((t,i)=>`<div class="cl-slide ${i===cur?'on':''}" role="group" aria-roledescription="slide" aria-label="${i+1} of 4" style="--h:${i*70+200}">${t}</div>`).join('')}</div><div class="cl-row" style="justify-content:space-between"><span class="cl-muted" style="font-size:13px">${cur+1} of 4 · ${['Glass','Clay','Aurora','Zine'][cur]}</span><div class="cl-row">${btn(ic('left'),'icon','aria-label="Previous slide"')}${btn(ic('right'),'icon '+(v==='focus'?'is-focus':''),`aria-label="Next slide" ${cur===3?'disabled':''}`)}</div></div></section>`;},
  css:'.cl-car{width:380px;display:grid;gap:12px}.cl-slides{display:flex;gap:10px;overflow:hidden}.cl-slide{flex:0 0 46%;height:120px;border-radius:var(--cl-radius);display:flex;align-items:flex-end;padding:12px;font:var(--cl-weight) 18px var(--cl-display);color:#fff;background:linear-gradient(140deg,hsl(var(--h) 70% 60%),hsl(calc(var(--h) + 40) 70% 40%));opacity:.55;transform:scale(.94);transition:.3s}.cl-slide.on{opacity:1;transform:none}',
  a11y:{role:'region with aria-roledescription="carousel"; slides as groups',keys:['Tab: previous / next buttons','Enter: change slide'],notes:'No autoplay by default; if it rotates, provide pause. Name the current slide in text.',wcag:['2.2.2 Pause, stop, hide']}},
 {id:'C39',name:'Resizable split panes',v:V('default:60 / 40','drag:Dragging','min:At minimum'),
  html:v=>{const w=v==='min'?22:v==='drag'?48:60;return `<div class="cl-split cl-surface"><div class="cl-pane" style="width:${w}%"><b>Board</b><span class="cl-muted">${w}%</span></div><div class="cl-divider ${v==='drag'?'is-drag':''}" role="separator" aria-orientation="vertical" aria-valuenow="${w}" aria-valuemin="22" aria-valuemax="78" tabindex="0"><i></i></div><div class="cl-pane" style="flex:1"><b>Inspector</b><span class="cl-muted">${100-w}%</span></div></div>`;},
  css:'.cl-split{display:flex;width:420px;height:160px;overflow:hidden;padding:0}.cl-pane{display:grid;align-content:center;justify-items:center;gap:4px;font-size:14px}.cl-divider{width:12px;display:grid;place-items:center;cursor:col-resize;background:color-mix(in srgb,var(--cl-line) 50%,transparent)}.cl-divider i{width:3px;height:36px;border-radius:9px;background:var(--cl-muted)}.cl-divider.is-drag{background:color-mix(in srgb,var(--cl-accent) 25%,transparent)}.cl-divider.is-drag i{background:var(--cl-accent)}',
  a11y:{role:'separator with aria-valuenow, focusable',keys:['← →: resize','Home / End: min / max','Enter: collapse'],notes:'Keyboard resizing is required; dragging is only one way. Respect minimum widths.',wcag:['2.5.7 Dragging movements','2.1.1 Keyboard']}},
 {id:'C40',name:'Responsive app shells',v:V('default:Desktop','phone:Phone'),
  html:v=>v==='phone'?`<div class="cl-shell phone cl-surface"><header>${ic('menu')}<b>Atlas</b>${ic('search')}</header><main><span class="cl-skel"></span><span class="cl-skel" style="width:70%"></span><div class="cl-tile"></div><div class="cl-tile"></div></main><nav>${['home','search','bookmark','user'].map((n,i)=>`<span class="${i===0?'on':''}">${ic(n)}</span>`).join('')}</nav></div>`:`<div class="cl-shell cl-surface"><header><b>Atlas</b><span class="cl-muted">Projects · Library · Updates</span>${ic('user')}</header><div class="cl-shellbody"><aside>${['home','grid','folder','bell'].map((n,i)=>`<span class="${i===1?'on':''}">${ic(n)}</span>`).join('')}</aside><main><span class="cl-skel" style="width:40%"></span><div class="cl-tiles"><div class="cl-tile"></div><div class="cl-tile"></div><div class="cl-tile"></div></div></main></div></div>`,
  css:'.cl-shell{width:440px;height:240px;display:grid;grid-template-rows:auto 1fr;overflow:hidden;padding:0;font-size:13px}.cl-shell header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;border-bottom:1px solid var(--cl-line)}.cl-shellbody{display:grid;grid-template-columns:52px 1fr}.cl-shell aside{display:grid;align-content:start;gap:6px;padding:10px 8px;border-right:1px solid var(--cl-line)}.cl-shell aside span,.cl-shell nav span{display:grid;place-items:center;height:34px;border-radius:var(--cl-radius-sm);color:var(--cl-muted)}.cl-shell .on{background:color-mix(in srgb,var(--cl-accent) 14%,transparent);color:var(--cl-accent)!important}.cl-shell main{padding:12px;display:grid;gap:10px;align-content:start}.cl-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.cl-tile{height:70px;border-radius:var(--cl-radius-sm);background:color-mix(in srgb,var(--cl-accent) 16%,var(--cl-bg))}.cl-shell.phone{width:220px;height:380px;grid-template-rows:auto 1fr auto;border-radius:26px}.cl-shell.phone nav{display:grid;grid-template-columns:repeat(4,1fr);padding:6px;border-top:1px solid var(--cl-line)}.cl-skel{display:block;height:12px;border-radius:6px;background:color-mix(in srgb,var(--cl-muted) 22%,transparent)}',
  a11y:{role:'banner, navigation, main landmarks',keys:['Skip link to main','Tab order follows the visual order'],notes:'Desktop side rail becomes a bottom bar on phones; the same destinations in the same order.',wcag:['2.4.1 Bypass blocks','1.3.2 Meaningful sequence']}}
 ];

 function cal(sel,v=''){
  const days=['Mo','Tu','We','Th','Fr','Sa','Su'];let h=`<div class="cl-cal"><div class="cl-row" style="justify-content:space-between;margin-bottom:8px"><button class="cl-btn icon" aria-label="Previous month" style="min-height:28px;width:28px;box-shadow:none;border:0">${ic('left')}</button><b style="font-size:14px">November 2026</b><button class="cl-btn icon" aria-label="Next month" style="min-height:28px;width:28px;box-shadow:none;border:0">${ic('right')}</button></div><div class="cl-calgrid" role="grid">`;
  h+=days.map(d=>`<span class="dh" role="columnheader">${d}</span>`).join('');
  for(let i=0;i<6;i++)h+='<span></span>';
  for(let d=1;d<=30;d++){const inRange=v==='range'&&d>=sel&&d<=sel+5;const isSel=d===sel||(v==='range'&&d===sel+5);h+=`<button class="${isSel?'sel':''}${inRange&&!isSel?' rng':''}${d===9?' today':''}${v==='focus'&&d===16?' is-focus':''}" role="gridcell" ${isSel?'aria-selected="true"':''}>${d}</button>`;}
  return h+'</div></div>';
 }
 const CAL_CSS='.cl-calgrid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center;font-size:13px}.cl-calgrid .dh{font-size:11px;color:var(--cl-muted);font-weight:700;padding:4px 0}.cl-calgrid button{all:unset;height:32px;display:grid;place-items:center;border-radius:var(--cl-radius-sm);cursor:pointer}.cl-calgrid .today{box-shadow:inset 0 0 0 1.5px var(--cl-accent);font-weight:700}.cl-calgrid .sel{background:var(--cl-accent);color:var(--cl-on-accent);font-weight:700}.cl-calgrid .rng{background:color-mix(in srgb,var(--cl-accent) 14%,transparent)}.cl-calgrid .is-focus{outline:2px solid var(--cl-accent);outline-offset:1px}';
 C.find(c=>c.id==='C11').css+=CAL_CSS;C.find(c=>c.id==='C12').css+=CAL_CSS;

 /* ---------- Lab UI ---------- */
 const S={comp:'C01',theme:'S05',mode:'light',density:'comfortable',label:'',icon:false,tab:'code',codeLang:'html'};
 try{Object.assign(S,JSON.parse(localStorage.getItem('atlasComponentLab')||'{}'));}catch{}
 const save=()=>{try{localStorage.setItem('atlasComponentLab',JSON.stringify(S));}catch{}};
 let root,stage,styleEl;

 function css(comp){return BASE+'\n'+(comp?.css||C.map(c=>c.css).join('\n'));}
 function apply(el){const t=AtlasThemes.byId[S.theme];AtlasThemes.loadFonts(t);const vars=AtlasThemes.vars(t,S.mode,S.density);for(const [k,v] of Object.entries(vars))el.style.setProperty(k,v);el.dataset.theme=S.theme;el.dataset.mode=S.mode;}

 function build(){
  const page=document.getElementById('ux');if(!page||document.getElementById('componentLab'))return;
  styleEl=document.createElement('style');styleEl.id='componentLabCSS';styleEl.textContent=css();document.head.append(styleEl);
  root=document.createElement('section');root.id='componentLab';root.className='clab';root.setAttribute('aria-label','Component lab');
  const themeOpts=AtlasThemes.list.map(t=>`<option value="${t.id}">${t.id} · ${t.name}</option>`).join('');
  root.innerHTML=`<div class="clab-head"><div><p class="clab-kicker">Component lab · 40 native components · 20 themes</p><h2>Every state, in every style.</h2></div><p>Pick a component, then a style. Each one is real HTML and CSS: crisp at any size, keyboard-ready, and the code below is exactly what you see.</p></div>
  <div class="clab-bar" role="toolbar" aria-label="Lab settings">
   <label>Style<select id="clTheme">${themeOpts}</select></label>
   <div class="clab-seg" role="group" aria-label="Colour mode"><button type="button" data-mode="light">Light</button><button type="button" data-mode="dark">Dark</button></div>
   <div class="clab-seg" role="group" aria-label="Density"><button type="button" data-density="comfortable">Comfortable</button><button type="button" data-density="compact">Compact</button></div>
   <label class="clab-grow">Label text<input id="clLabel" type="text" maxlength="40" placeholder="Use your own words"></label>
   <label class="clab-check"><input id="clIcon" type="checkbox"> Leading icon</label>
  </div>
  <div class="clab-body">
   <nav class="clab-list" aria-label="Components"><label class="clab-search"><span class="clab-sr">Filter components</span><input id="clFilter" type="search" placeholder="Filter 40 components"></label><ol id="clList"></ol></nav>
   <div class="clab-main">
    <div class="clab-title"><div><span id="clCode" class="clab-kicker"></span><h3 id="clName"></h3></div><span id="clCount" class="clab-kicker"></span></div>
    <div id="clStage" class="clab-stage cl-root"></div>
    <div class="clab-live"><p class="clab-kicker">Try it · the interactive version responds to hover, focus and keyboard</p><div id="clLive" class="clab-livebox cl-root"></div></div>
    <div class="clab-tabs" role="tablist"><button role="tab" data-tab="code">Code</button><button role="tab" data-tab="a11y">Accessibility</button><button role="tab" data-tab="notes">Guidance</button></div>
    <div id="clPanel" class="clab-panel" role="tabpanel"></div>
   </div>
  </div>`;
  const grid=document.getElementById('componentGrid');
  const anchor=page.querySelector('.filters')||grid;
  anchor.parentNode.insertBefore(root,anchor);
  // the old static grid becomes the index below the lab
  if(grid){const h=document.createElement('h2');h.className='clab-indexhead';h.textContent='All 40 at a glance';grid.parentNode.insertBefore(h,page.querySelector('.filters')||grid);}
  stage=root.querySelector('#clStage');
  root.querySelector('#clTheme').value=S.theme;root.querySelector('#clLabel').value=S.label;root.querySelector('#clIcon').checked=S.icon;
  root.querySelector('#clTheme').onchange=e=>{S.theme=e.target.value;render();};
  root.querySelectorAll('button[data-mode]').forEach(b=>b.onclick=()=>{S.mode=b.dataset.mode;render();});
  root.querySelectorAll('button[data-density]').forEach(b=>b.onclick=()=>{S.density=b.dataset.density;render();});
  root.querySelector('#clLabel').oninput=e=>{S.label=e.target.value;render(false);};
  root.querySelector('#clIcon').onchange=e=>{S.icon=e.target.checked;render(false);};
  root.querySelector('#clFilter').oninput=list;
  root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.tab;panel();save();});
  root.querySelector('.clab-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;const tabs=[...root.querySelectorAll('[data-tab]')];const i=tabs.findIndex(t=>t.dataset.tab===S.tab);const n=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];S.tab=n.dataset.tab;panel();n.focus();});
  // grid cards open the component in the lab
  grid?.addEventListener('click',e=>{const b=e.target.closest('[data-open^="C"]');if(!b)return;e.preventDefault();e.stopPropagation();select(b.dataset.open);root.scrollIntoView({behavior:'smooth',block:'start'});},true);
  const linkId=(location.hash.match(/[?&]component=(C\d\d)/)||[])[1];if(linkId)S.comp=linkId;const linkTheme=(location.hash.match(/[?&]theme=(S\d\d)/)||[])[1];if(linkTheme&&AtlasThemes.byId[linkTheme])S.theme=linkTheme;root.querySelector('#clTheme').value=S.theme;
  list();render();
 }
 function list(){
  const q=(root.querySelector('#clFilter').value||'').toLowerCase();
  root.querySelector('#clList').innerHTML=C.filter(c=>!q||(c.name+' '+c.id).toLowerCase().includes(q)).map(c=>`<li><button type="button" data-c="${c.id}" aria-current="${c.id===S.comp}"><span>${c.id.slice(1)}</span>${c.name}</button></li>`).join('')||'<li class="clab-none">No component matches.</li>';
  root.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>select(b.dataset.c));
 }
 function select(id){S.comp=id;list();render();}
 function render(full=true){
  const c=C.find(x=>x.id===S.comp)||C[0];const p={label:S.label,icon:S.icon};
  apply(stage);apply(root.querySelector('#clLive'));
  root.querySelector('#clCode').textContent=c.id+' / UX/UI components';
  root.querySelector('#clName').textContent=c.name;
  root.querySelector('#clCount').textContent=`${c.v.length} states`;
  stage.innerHTML=c.v.map(([k,l])=>`<figure class="clab-cell"><figcaption>${l}</figcaption><div class="clab-cellbody" inert>${c.html(k,p)}</div></figure>`).join('');
  root.querySelector('#clLive').innerHTML=c.html(c.v[0][0],p);
  root.querySelectorAll('button[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===S.mode)));
  root.querySelectorAll('button[data-density]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.density===S.density)));
  root.querySelectorAll('[data-c]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.c===S.comp)));
  panel();save();
 }
 function react(html){return html.replace(/\bclass=/g,'className=').replace(/\bfor=/g,'htmlFor=').replace(/\bstroke-width=/g,'strokeWidth=').replace(/\bstroke-linecap=/g,'strokeLinecap=').replace(/\bstroke-linejoin=/g,'strokeLinejoin=').replace(/\btabindex=/g,'tabIndex=').replace(/ (disabled|inert)(?=[ >])/g,' $1').replace(/style="([^"]*)"/g,(m,s)=>'style={{'+s.split(';').filter(Boolean).map(d=>{const [k,...v]=d.split(':');return k.trim().replace(/-([a-z])/g,(_,c)=>c.toUpperCase()).replace(/^--/,"'--")+(k.trim().startsWith('--')?"'":'')+":'"+v.join(':').trim()+"'";}).join(',')+'}}').replace(/<input([^>]*[^/])>/g,'<input$1 />');}
 function pretty(html){return html.replace(/></g,'>\n<');}
 function panel(){
  const c=C.find(x=>x.id===S.comp)||C[0];const t=AtlasThemes.byId[S.theme];
  root.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===S.tab;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});
  const P=root.querySelector('#clPanel');
  if(S.tab==='code'){
   const vars=AtlasThemes.vars(t,S.mode,S.density);
   const tokenCss=`.cl-root{\n${Object.entries(vars).map(([k,v])=>`  ${k}: ${v};`).join('\n')}\n}`;
   const html=`<div class="cl-root">\n${pretty(c.html(c.v[0][0],{label:S.label,icon:S.icon}))}\n</div>`;
   const code={html,css:tokenCss+'\n'+css(c).replace(/\}/g,'}\n'),react:`export function ${c.name.replace(/[^A-Za-z]/g,'')}() {\n  return (\n${react(html).split('\n').map(l=>'    '+l).join('\n')}\n  );\n}`,tokens:JSON.stringify(AtlasThemes.tokensJSON(t,S.mode),null,2)};
   P.innerHTML=`<div class="clab-codebar" role="group" aria-label="Code format">${[['html','HTML'],['css','CSS'],['react','React'],['tokens','Tokens JSON']].map(([k,l])=>`<button type="button" data-lang="${k}" aria-pressed="${S.codeLang===k}">${l}</button>`).join('')}<button type="button" class="clab-copy" id="clCopy">Copy</button></div><pre class="clab-pre"><code id="clCodeOut"></code></pre><p class="clab-note">${t.name} · ${S.mode} · ${S.density}. Fonts: ${t.fonts.display}${t.fonts.body!==t.fonts.display?' + '+t.fonts.body:''}${t.shape.system?' (system)':' from Google Fonts'}.</p>`;
   P.querySelector('#clCodeOut').textContent=code[S.codeLang];
   P.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{S.codeLang=b.dataset.lang;panel();save();});
   P.querySelector('#clCopy').onclick=async e=>{const btn=e.currentTarget;try{await navigator.clipboard.writeText(code[S.codeLang]);btn.textContent='Copied';}catch{const r=document.createRange();r.selectNodeContents(P.querySelector('#clCodeOut'));const s=getSelection();s.removeAllRanges();s.addRange(r);btn.textContent='Selected · press ⌘C';}setTimeout(()=>btn.textContent='Copy',1800);};
  }else if(S.tab==='a11y'){
   P.innerHTML=`<dl class="clab-dl"><dt>Role</dt><dd>${esc(c.a11y.role)}</dd><dt>Keyboard</dt><dd><ul>${c.a11y.keys.map(k=>`<li>${esc(k)}</li>`).join('')}</ul></dd><dt>Notes</dt><dd>${esc(c.a11y.notes)}</dd><dt>WCAG 2.2</dt><dd class="clab-wcag">${c.a11y.wcag.map(w=>`<span>${esc(w)}</span>`).join('')}</dd></dl>`;
  }else{
   const e=(typeof catalogue!=='undefined'?catalogue:[]).find(x=>x.id===c.id)||{};
   P.innerHTML=`<dl class="clab-dl">${[['What to notice',e.cues],['Best for',e.use],['Build',e.build],['Watch out',e.avoid],['Motion',e.motion]].filter(r=>r[1]).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')||'<dd>Guidance loads with the catalogue.</dd>'}</dl>`;
  }
 }
 window.ComponentLab={components:C,build,select,css:()=>css()};
 const tryBuild=()=>{if(document.getElementById('ux'))build();};
 if(document.readyState!=='loading')tryBuild();else addEventListener('DOMContentLoaded',tryBuild);
 addEventListener('hashchange',()=>{if(!root)return;const th=(location.hash.match(/[?&]theme=(S\d\d)/)||[])[1];if(th&&AtlasThemes.byId[th]){S.theme=th;root.querySelector('#clTheme').value=th;}const id=(location.hash.match(/[?&]component=(C\d\d)/)||[])[1];if(id)select(id);else if(th)render();if(id||th)setTimeout(()=>root.scrollIntoView({block:'start'}),300);});
})();
